package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.history.History;

/** A statement taken of a person: the sheet's today then, or the date it was taken as of, their due-total
 *  then (none when it was n/a) and how many of their claims counted. */
@Entity
@EntityListeners(History.class)
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    @Column(name = "due_total")
    private BigDecimal dueTotal;

    @Column(name = "claim_count", nullable = false)
    private int claimCount;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, LocalDate takenOn, BigDecimal dueTotal, int claimCount) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.takenOn = takenOn;
        this.dueTotal = dueTotal;
        this.claimCount = claimCount;
    }

    /** The same statement, taken of another person (on this sheet or another). */
    public Statement copyTo(String otherSheetId, Long otherPersonId) {
        return new Statement(otherSheetId, otherPersonId, takenOn, dueTotal, claimCount);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public BigDecimal getDueTotal() {
        return dueTotal;
    }

    public int getClaimCount() {
        return claimCount;
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The sheet's statements in the order they were taken. */
    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    /** The person's statements in the order they were taken. */
    List<Statement> findByPersonIdOrderByIdAsc(Long personId);
}
-- A statement taken of a person: the sheet's today when it was taken, the person's due-total then
-- (none when it showed n/a) and how many of their claims counted. Listed in the order taken (by id).
CREATE TABLE statement (
    id          BIGINT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id    VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id   BIGINT         NOT NULL REFERENCES person (id),
    taken_on    DATE           NOT NULL,
    due_total   DECIMAL(15, 2),
    claim_count INT            NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);

-- A claim bound by its person's last statement shows and totals the figure it had then (none when
-- that was n/a), whatever later rate or grade changes would make it, until the next statement.
ALTER TABLE claim ADD COLUMN stated BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
